-- C12 / P12.6 — reusable service-business specialist profile with company/project isolation.
create table if not exists public.command_center_service_business_binding_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 binding_event_id text not null check(btrim(binding_event_id)<>''), binding_id text not null check(btrim(binding_id)<>''), project_id text not null check(btrim(project_id)<>''), company_id text not null check(btrim(company_id)<>''), crm_ref text not null check(btrim(crm_ref)<>''), calendar_ref text, payment_provider_ref text, source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,binding_event_id), unique(owner_id,binding_id), unique(owner_id,project_id,observed_at), check(calendar_ref is null or btrim(calendar_ref)<>''), check(payment_provider_ref is null or btrim(payment_provider_ref)<>'')
);
create table if not exists public.command_center_service_business_state_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 state_event_id text not null check(btrim(state_event_id)<>''), state_id text not null check(btrim(state_id)<>''), project_id text not null check(btrim(project_id)<>''), company_id text not null check(btrim(company_id)<>''), domain text not null check(domain in ('lead','estimate','contract','job','material','schedule','payment','follow_up','reputation')), canonical_ref text not null check(btrim(canonical_ref)<>''), state text not null check(btrim(state)<>''), provider_ref text, source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,state_event_id), unique(owner_id,state_id), check(provider_ref is null or btrim(provider_ref)<>'')
);
create or replace function public.command_center_reject_service_business_history_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Service-business specialist evidence is immutable'; end $$;
drop trigger if exists command_center_service_business_binding_immutable on public.command_center_service_business_binding_history; create trigger command_center_service_business_binding_immutable before update or delete on public.command_center_service_business_binding_history for each row execute function public.command_center_reject_service_business_history_mutation();
drop trigger if exists command_center_service_business_state_immutable on public.command_center_service_business_state_history; create trigger command_center_service_business_state_immutable before update or delete on public.command_center_service_business_state_history for each row execute function public.command_center_reject_service_business_history_mutation();
alter table public.command_center_service_business_binding_history enable row level security; alter table public.command_center_service_business_state_history enable row level security;
revoke all on table public.command_center_service_business_binding_history,public.command_center_service_business_state_history from public,anon,authenticated; grant select,insert on table public.command_center_service_business_binding_history,public.command_center_service_business_state_history to authenticated;
create policy p12_6_service_business_binding_owner on public.command_center_service_business_binding_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p12_6_service_business_state_owner on public.command_center_service_business_state_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
